// src/components/Layout.jsx
import React from "react";
import "./Layout.css";

const Layout = ({ asideIzq, main, asideDer }) => {
  return (
    <div className="home-grid">
      {asideIzq}
      {main}
      {asideDer}
      <footer style={{ gridArea: "footer", textAlign: "center", padding: "1rem", background: "#bfd5f1" }}>
        &copy; {new Date().getFullYear()} MySpace
      </footer>
    </div>
  );
};

export default Layout;
